scriptedGuis.rawSource:
cannibalism_warlord_command_scripted_gui = {
		context_type = decision_category
		window_name = "cannibalism_warlord_command_window"
		visible = {
			is_ai = no
			is_cannibalism_warlord_country = yes
			NOT = { has_global_flag = cannibalism_reveal_complete }
			NOT = { has_global_flag = world_end }
		}
		triggers = {
			cannibalism_alignment_meter_visible = { has_global_flag = cannibalism_evolution_ii_active }
			cannibalism_alignment_value_visible = { has_global_flag = cannibalism_evolution_ii_active }
			cannibalism_warlord_route_animated_visible = { always = yes }
			cannibalism_warlord_route_static_visible = { always = no }
			cannibalism_larder_glow_animated_visible = {
				OR = {
					check_variable = { cannibalism_larder < constant:cannibalism_consumption.larder_low }
					check_variable = { cannibalism_larder > constant:cannibalism_consumption.larder_abundant }
				}
			}
			cannibalism_larder_glow_static_visible = { always = no }
			cannibalism_frenzy_border_animated_visible = {
				check_variable = { cannibalism_frenzy > constant:cannibalism_meter.severe }
			}
			cannibalism_frenzy_border_static_visible = { always = no }
		}
		ai_enabled = { always = no }
	}

